package com.garmentfactory.storage.api;

import java.util.Optional;

/**
 * Port for storing files by key. Callers never build paths: keys are generated by the server
 * (for example products/{productId}/{imageId}.png). Provider-specific code lives in integration.*.
 */
public interface FileStorage {

    void put(String key, byte[] content);

    Optional<byte[]> get(String key);

    /** Best effort: a file that is already gone is not an error. */
    void delete(String key);
}